package com.ems.controller; import com.ems.dao.EmployeeDAO; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; @WebServlet({"/employees/new","/employees/edit"}) public class EmployeeFormServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String path=r.getServletPath();try{if(path.endsWith("edit")){long id=Long.parseLong(r.getParameter("id"));r.setAttribute("employee",new EmployeeDAO().findById(id));r.getRequestDispatcher("/WEB-INF/views/edit-employee.jsp").forward(r,s);}else r.getRequestDispatcher("/WEB-INF/views/add-employee.jsp").forward(r,s);}catch(Exception e){s.sendRedirect(r.getContextPath()+"/employees?error=invalid");}}}
